<?php require 'includes/database.php';require 'includes/auth.php';requireLogin('customer');$id=(int)($_GET['id']??$_POST['id']??0);$st=$pdo->prepare("SELECT b.*,s.name shop_name,sv.name service_name FROM bookings b JOIN shops s ON s.id=b.shop_id JOIN services sv ON sv.id=b.service_id WHERE b.id=? AND b.customer_id=?");$st->execute([$id,$_SESSION['user']['id']]);$b=$st->fetch();if(!$b)exit('Booking not found');if($_SERVER['REQUEST_METHOD']==='POST'){$pdo->prepare("UPDATE bookings SET payment_status='paid',booking_status='confirmed' WHERE id=?")->execute([$id]);header('Location: mybooking.php');exit;}require 'includes/header.php';?><main class="wrap"><form class="form card" method="post"><h2>ชำระมัดจำ</h2><p><?=htmlspecialchars($b['shop_name'])?> / <?=htmlspecialchars($b['service_name'])?></p><h1><?=number_format($b['deposit_amount'],0)?> บาท</h1><p class="muted">กติกา: ราคาไม่เกิน 200 บาท มัดจำ 50 บาท / เกิน 200 บาท มัดจำ 100 บาท</p><input type="hidden" name="id" value="<?=$id?>"><label>ช่องทางชำระ</label><select><option>ธนาคาร / QR</option><option>TrueMoney Wallet</option></select><button class="btn">ยืนยันชำระเงิน (Demo)</button></form></main><?php require 'includes/footer.php';?>
